def-struct-hyp(
    list-partial(
        Type.annotation(@A, Set(T@Set.ctxt.T)),
        Type.annotation(
            @$\mathcal{C}$,
            Set(Set(T@Set.ctxt.T))
        ),
        Set.subset(A, S@Topology.ctxt.S)
    ),
    Topology.openCover($\mathcal{C}$, A),
    struct(
        member[colon](
            %开集族%,
            Set.subset($\mathcal{C}$, τ@Topology.ctxt.tau)
        ),
        member[colon](
            %覆盖性%,
            Set.subset(
                A,
                Set.sep-typed(
                    @x,
                    T@Set.ctxt.T,
                    Logic.exists-typed(@U, Set(T@Set.ctxt.T), Logic.and(Set.mem(U, $\mathcal{C}$), Set.mem(x, U)))
                )
            )
        )
    )
)
